package sn.ucad.nexora.espace.infrastructure.security.jwt;
import java.io.IOException; import java.util.ArrayList; import java.util.Collection; import java.util.List; import java.util.UUID; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import io.jsonwebtoken.Claims; import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.*;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter{private final JwtProviderAdapter jwt;public JwtAuthenticationFilter(JwtProviderAdapter j){jwt=j;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h==null||!h.startsWith("Bearer ")){chain.doFilter(req,res);return;}try{Claims c=jwt.parseToken(h.substring(7));if(!"ACCESS".equals(c.get("type",String.class)))throw new IllegalArgumentException();UUID id=UUID.fromString(c.getSubject());List<SimpleGrantedAuthority>a=new ArrayList<>();Object roles=c.get("roles");if(roles instanceof Collection<?> rr)for(Object role:rr)if(role!=null)a.add(new SimpleGrantedAuthority("ROLE_"+role));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(id,null,a));}catch(Exception e){SecurityContextHolder.clearContext();}chain.doFilter(req,res);}}
